$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$o="$root\M78ClosureResults";$s="$root\M78ClosureEditor"
function Upload($p,$n){Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null}
try{
 if(!(Test-Path $s)){throw 'Expected verified compressed editor objects absent'};if((Get-PSDrive C).Free -lt 22MB){throw 'Insufficient bounded compressed editor headroom'}
 $m=(Invoke-WebRequest -UseBasicParsing "$base/m78-final2-repair-editor.json").Content|ConvertFrom-Json;$engine=[IO.File]::ReadAllText("$o\m78-closure-engine.json")|ConvertFrom-Json;if((Get-FileHash $engine.archive.path).Hash.ToLower() -ne $engine.archive.sha256){throw 'Frozen archive mismatch'};foreach($u in $engine.objects){if((Get-FileHash $u.path).Hash.ToLower() -ne $u.sha256){throw 'Closure object mismatch'}}
 $objs=@();$rows=@();foreach($u in $m.objects){$src=Join-Path "$root\Source" $u.source;if((Get-FileHash $src).Hash.ToLower() -ne $u.sourceSHA256){throw 'Editor source mismatch'};$obj="$s\$($u.objectName)";if(!(Test-Path $obj)){throw 'Verified existing object absent'};if((Get-Item $obj).Length -ne $u.bytes -or (Get-FileHash $obj).Hash.ToLower() -ne $u.objectSHA256){throw 'Unchanged editor object mismatch'};$objs+=$obj;$rows+=$u}
 Import-Module "$root\VS2022\Common7\Tools\Microsoft.VisualStudio.DevShell.dll";Enter-VsDevShell -VsInstallPath "$root\VS2022" -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64';Set-Location "$root\Build";$exe="$root\Build\Release\m78-closure-editor_v3.exe";if(Test-Path $exe){throw 'Preserve existing executable'}
 $link=[string]$m.linkFlags;$link=[regex]::Replace($link,'/OUT:"[^"]*"',('/OUT:"'+$exe+'"'),'IgnoreCase');$replacement=(($engine.objects|ForEach-Object {'"'+$_.path+'"'})-join ' ')+' "'+$engine.archive.path+'"';$link=[regex]::Replace($link,'RELEASE\\JUDAS_ENGINE\.LIB','','IgnoreCase');$link=$replacement+' '+$link;$link=[regex]::Replace($link,'/PDB:"[^"]*"',('/PDB:"'+$s+'\link.pdb"'),'IgnoreCase');$link=[regex]::Replace($link,'/IMPLIB:"[^"]*"',('/IMPLIB:"'+$s+'\editor.lib"'),'IgnoreCase');$link=[regex]::Replace($link,'\s+JUDAS_EDITOR\.DIR\\RELEASE\\[^\s]+\.OBJ',' ','IgnoreCase');foreach($obj in $objs){$link+=' "'+$obj+'"'};$map="$o\m78-closure-editor_v3.map";$link+=' /MAP:"'+$map+'" /VERBOSE:LIB';$rsp="$s\link.rsp";[IO.File]::WriteAllText($rsp,$link,[Text.UTF8Encoding]::new($false));$log="$o\m78-closure-editor_v3-link.log";$ErrorActionPreference='Continue';& link.exe "@$rsp" 2>&1|Tee-Object -FilePath $log;$code=$LASTEXITCODE;$ErrorActionPreference='Stop';Upload $log ([IO.Path]::GetFileName($log));if($code -ne 0){throw 'Final editor link failed'};Upload $map ([IO.Path]::GetFileName($map));if([IO.File]::ReadAllText($log) -match '(?im)^\s*Loaded\s+.*judas_engine\.lib\([^\)\r\n]*(PhysicsWorld|WorldPersistence)\.obj\)'){throw 'Stale replaced member extracted'}
 $owned="$o\editor-project";if(Test-Path $owned){throw 'Preserve prior editor project'};Copy-Item "$root\Source\projects\balance_lab" $owned -Recurse;$scene="$owned\Scenes\standing.judas";$before=(Get-FileHash $scene).Hash.ToLower();$env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";$env:JUDAS_EDITOR_AUTOTEST="$o\editor-autotest";$env:APPDATA="$o\editor-userdata\Roaming";$env:LOCALAPPDATA="$o\editor-userdata\Local";foreach($n in @('JUDAS_TEST_SCRIPT','M78_DIAGNOSTIC_PERSIST_DRIVE_IMPULSES','JUDAS_BOUNDARY_REPLAY_CAPTURED_NATIVE','JUDAS_BOUNDARY_REPLAY_MODE')){[Environment]::SetEnvironmentVariable($n,$null,'Process')}
 $w=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process -FilePath $exe -WorkingDirectory "$root\Source" -ArgumentList @("$owned\balance_lab.judasproj") -PassThru -RedirectStandardOutput "$o\m78-closure-editor_v3.stdout.log" -RedirectStandardError "$o\m78-closure-editor_v3.stderr.log";[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;$exit='owned editor deadline'}else{$p.Refresh();$exit=$p.ExitCode};$w.Stop();$after=(Get-FileHash $scene).Hash.ToLower();$observations=@();foreach($f in Get-ChildItem $o -File -Filter 'editor-autotest*'){$name='m78-closure-editor_v3-'+$f.Name;Upload $f.FullName $name;$observations+=@{name=$name;bytes=$f.Length;sha256=(Get-FileHash $f.FullName).Hash.ToLower()}}
 $smoke=@{scope='Final source explicit-PW/WP link, unchanged editor-source objects; copied ordinary project edit/duplicate/undo/Play/Stop/save. NativeWindows softwareGL functionality only.';exitCode=$exit;seconds=$w.Elapsed.TotalSeconds;authoredScene=$scene;sceneBeforeSHA256=$before;sceneAfterSHA256=$after;sceneUnchanged=($before -eq $after);observations=$observations;freeBytes=(Get-PSDrive C).Free};$rp="$o\m78-closure-editor_v3-smoke.json";$smoke|ConvertTo-Json -Depth 6|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp));Upload "$o\m78-closure-editor_v3.stdout.log" 'm78-closure-editor_v3.stdout.log';Upload "$o\m78-closure-editor_v3.stderr.log" 'm78-closure-editor_v3.stderr.log'
 $files=@();foreach($p in @($exe)+$objs){$files+=@{path=$p;name=[IO.Path]::GetFileName($p);bytes=(Get-Item $p).Length;sha256=(Get-FileHash $p).Hash.ToLower()};Upload $p ('m78-closure-editor_v3-'+[IO.Path]::GetFileName($p)+'.bin')}
 $rp="$o\m78-closure-editor_v3-build.json";@{scope=$smoke.scope;case='editor_v3';archive=$engine.archive;replacementObjects=$engine.objects;reusedInputs=$rows;executable=$exe;executableSHA256=(Get-FileHash $exe).Hash.ToLower();executableBytes=(Get-Item $exe).Length;linkerResponse=$link;frozenReplacedMembersNotExtracted=$true;runs=@(@{run='editor-smoke';exitCode=$exit;expectedExitCode=0});generatedFiles=$files;ownedLargeEvidence=@($map,$log)|ForEach-Object{@{path=$_;name=[IO.Path]::GetFileName($_);bytes=(Get-Item $_).Length;sha256=(Get-FileHash $_).Hash.ToLower()}}}|ConvertTo-Json -Depth 8|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp))
}catch{$_|Out-String|Set-Content "$o\m78-closure-editor_v3-error.txt";Upload "$o\m78-closure-editor_v3-error.txt" 'm78-closure-editor_v3-error.txt';exit 1}
